// Tests for the code generated by gen.RPC, using the defs fixture.
package rpctest_test

//go:generate go run ./generate

import (
	"bytes"
	"cmp"
	"compress/gzip"
	"context"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"net/http/httptest"
	"os"
	"reflect"
	"strings"
	"testing"

	"github.com/peterhellberg/kop/gen"
	"github.com/peterhellberg/kop/gen/internal/rpctest"
	"github.com/peterhellberg/kop/gen/internal/rpctest/defs"
)

func TestGenerated(t *testing.T) {
	var buf bytes.Buffer

	if err := gen.RPC(&buf, "rpctest", reflect.TypeFor[defs.List]()); err != nil {
		t.Fatal(err)
	}

	want, err := os.ReadFile("gen.go")
	if err != nil {
		t.Fatal(err)
	}

	if !bytes.Equal(buf.Bytes(), want) {
		t.Error("gen.go is out of date; run go generate ./...")
	}
}

func TestJSONNames(t *testing.T) {
	b, err := json.Marshal(rpctest.ItemsRequest{
		Thing:  &rpctest.Thing{Name: "n", ID: "i", HTTPServer: "h", UserID: "u"},
		ByName: map[string][]rpctest.Thing{},
	})
	if err != nil {
		t.Fatal(err)
	}

	want := `{"thing":{"name":"n","children":null,"id":"i","httpServer":"h","userID":"u"}}`

	if string(b) != want {
		t.Errorf("got %s, want %s", b, want)
	}
}

// fakeList echoes the request items, or fails with err if set.
type fakeList struct{ err error }

func (f fakeList) Add(_ context.Context, r rpctest.AddRequest) (*rpctest.AddResponse, error) {
	return &rpctest.AddResponse{Items: r.Items}, f.err
}

func (f fakeList) Clear(context.Context, rpctest.ClearRequest) (*rpctest.ClearResponse, error) {
	return &rpctest.ClearResponse{}, f.err
}

func (f fakeList) Items(context.Context, rpctest.ItemsRequest) (*rpctest.ItemsResponse, error) {
	return &rpctest.ItemsResponse{Items: []string{"A"}}, f.err
}

// serve starts a test server for list and returns its URL. If wrap is not
// nil, it may configure the server before registration and returns the
// handler to serve.
func serve(t *testing.T, list rpctest.List, wrap func(*rpctest.Server) http.Handler) string {
	t.Helper()

	server := rpctest.NewServer()

	var h http.Handler = server
	if wrap != nil {
		h = wrap(server)
	}

	rpctest.RegisterList(server, list)

	ts := httptest.NewServer(h)
	t.Cleanup(ts.Close)

	return ts.URL
}

func client(endpoint string) *rpctest.ListClient {
	return rpctest.NewListClient(rpctest.New(endpoint))
}

func TestClient(t *testing.T) {
	c := client(serve(t, fakeList{}, nil) + "/rpc/")

	add, err := c.Add(t.Context(), rpctest.AddRequest{Items: []string{"Eggs", "Milk"}})
	if err != nil || strings.Join(add.Items, ",") != "Eggs,Milk" {
		t.Errorf("Add = %v, %v; want [Eggs Milk]", add, err)
	}

	items, err := c.Items(t.Context(), rpctest.ItemsRequest{})
	if err != nil || strings.Join(items.Items, ",") != "A" {
		t.Errorf("Items = %v, %v; want [A]", items, err)
	}

	if _, err := c.Clear(t.Context(), rpctest.ClearRequest{}); err != nil {
		t.Errorf("Clear: %v", err)
	}
}

func TestClientErrors(t *testing.T) {
	canceled, cancel := context.WithCancel(t.Context())
	cancel()

	stop := func(r *rpctest.RPC) { r.BeforeRequest = func(*http.Request) error { return errors.New("stop") } }

	for _, tt := range []struct {
		name  string
		list  fakeList
		wrap  func(*rpctest.Server) http.Handler
		path  string
		ctx   context.Context
		setup func(*rpctest.RPC)
		want  string
	}{
		{name: "handler error", list: fakeList{errors.New("out of milk")}, want: "out of milk"},
		{name: "non-JSON error", list: fakeList{errors.New("nope")}, want: "(418) custom: nope", wrap: func(s *rpctest.Server) http.Handler {
			s.OnErr = func(w http.ResponseWriter, _ *http.Request, err error) {
				http.Error(w, "custom: "+err.Error(), http.StatusTeapot)
			}
			return s
		}},
		{name: "wrong basepath", path: "/other/", want: "(404)"},
		{name: "canceled", ctx: canceled, want: context.Canceled.Error()},
		{name: "before request", setup: stop, want: "stop"},
	} {
		t.Run(tt.name, func(t *testing.T) {
			r := rpctest.New(serve(t, tt.list, tt.wrap) + cmp.Or(tt.path, "/rpc/"))
			if tt.setup != nil {
				tt.setup(r)
			}

			_, err := rpctest.NewListClient(r).Items(cmp.Or(tt.ctx, t.Context()), rpctest.ItemsRequest{})
			if err == nil || !strings.Contains(err.Error(), tt.want) {
				t.Errorf("err = %v, want containing %q", err, tt.want)
			}
		})
	}
}

func TestServer(t *testing.T) {
	gone := func(s *rpctest.Server) http.Handler {
		s.NotFound = http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) { w.WriteHeader(http.StatusGone) })
		return s
	}

	for _, tt := range []struct {
		name, method, path, body string
		list                     fakeList
		wrap                     func(*rpctest.Server) http.Handler
		code                     int
		want                     string
	}{
		{name: "wire format", path: "/rpc/List.Add", body: `{"items":["Beer"]}`, code: 200, want: "{\n  \"items\": [\n    \"Beer\"\n  ]\n}"},
		{name: "handler error", path: "/rpc/List.Items", list: fakeList{errors.New("out of milk")}, code: 500, want: `"error": "out of milk"`},
		{name: "invalid json", path: "/rpc/List.Add", body: `{`, code: 500, want: "decode"},
		{name: "body too large", path: "/rpc/List.Add", body: `{"items":["` + strings.Repeat("x", 1<<20) + `"]}`, code: 500, want: "decode"},
		{name: "GET", method: http.MethodGet, path: "/rpc/List.Items", code: 404},
		{name: "unknown method", path: "/rpc/List.Nope", code: 404},
		{name: "custom NotFound", path: "/rpc/List.Nope", wrap: gone, code: 410},
		{name: "custom Basepath", path: "/api/List.Items", code: 200, want: `"A"`, wrap: func(s *rpctest.Server) http.Handler {
			s.Basepath = "/api/"
			return s
		}},
	} {
		t.Run(tt.name, func(t *testing.T) {
			req, err := http.NewRequest(cmp.Or(tt.method, http.MethodPost), serve(t, tt.list, tt.wrap)+tt.path, strings.NewReader(cmp.Or(tt.body, "{}")))
			if err != nil {
				t.Fatal(err)
			}

			resp, err := http.DefaultClient.Do(req)
			if err != nil {
				t.Fatal(err)
			}
			defer resp.Body.Close()

			body, _ := io.ReadAll(resp.Body)

			if resp.StatusCode != tt.code || !strings.Contains(string(body), tt.want) {
				t.Errorf("got %d %q, want %d containing %q", resp.StatusCode, body, tt.code, tt.want)
			}
		})
	}
}

func TestBeforeRequest(t *testing.T) {
	var auth string

	r := rpctest.New(serve(t, fakeList{}, func(s *rpctest.Server) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) {
			auth = req.Header.Get("Authorization")
			s.ServeHTTP(w, req)
		})
	}) + "/rpc/")

	r.BeforeRequest = func(req *http.Request) error {
		req.Header.Set("Authorization", "Bearer token")
		return nil
	}

	if _, err := rpctest.NewListClient(r).Items(t.Context(), rpctest.ItemsRequest{}); err != nil || auth != "Bearer token" {
		t.Errorf("err = %v, Authorization = %q; want Bearer token", err, auth)
	}
}

// TestGzipResponse checks that the client handles a response compressed by
// a proxy, which requires the transport to negotiate gzip itself.
func TestGzipResponse(t *testing.T) {
	url := serve(t, fakeList{}, func(s *rpctest.Server) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			rec := httptest.NewRecorder()
			s.ServeHTTP(rec, r)

			w.Header().Set("Content-Encoding", "gzip")
			w.WriteHeader(rec.Code)

			zw := gzip.NewWriter(w)
			zw.Write(rec.Body.Bytes())
			zw.Close()
		})
	})

	if items, err := client(url+"/rpc/").Items(t.Context(), rpctest.ItemsRequest{}); err != nil || len(items.Items) != 1 {
		t.Errorf("Items = %v, %v; want [A]", items, err)
	}
}
